import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const sessionWith = (content: string): ChatSession => ({
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content, timestamp: new Date().toISOString()}],
});

const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('Reproduction #95: onError on non-Error rejections', () => {
  it('calls onError with a wrapped Error when a string is thrown', async () => {
    const callOrder: string[] = [];
    let seenError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        callOrder.push('onError');
        seenError = error;
      },
      afterSession: async () => {
        callOrder.push('afterSession');
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith('string boom'), promptBuilder, undefined, {hooks});

    const outcome = await orchestrator.processMessage(sessionWith('hello')).then(
      () => ({rejected: false}),
      reason => ({rejected: true, reason})
    );

    expect(outcome).toEqual({rejected: true, reason: 'string boom'});
    expect(callOrder).toEqual(['onError', 'afterSession']);
    expect(seenError).toBeInstanceOf(Error);
    expect(seenError?.message).toBe('string boom');
    expect(seenError?.cause).toBe('string boom');
  });

  it('calls onError with a wrapped Error when a plain object is thrown', async () => {
    const callOrder: string[] = [];
    let seenError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        callOrder.push('onError');
        seenError = error;
      },
      afterSession: async () => {
        callOrder.push('afterSession');
      },
    };

    const reason = {code: 503, detail: 'upstream down'};
    const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks});

    const outcome = await orchestrator.processMessage(sessionWith('hello')).then(
      () => ({rejected: false}),
      r => ({rejected: true, reason: r})
    );

    expect(outcome).toEqual({rejected: true, reason});
    expect(callOrder).toEqual(['onError', 'afterSession']);
    expect(seenError).toBeInstanceOf(Error);
    expect(seenError?.message).toContain('object'); // String([object Object]) usually
    expect(seenError?.cause).toBe(reason);
  });

  it('calls onError with a wrapped Error when undefined is thrown', async () => {
    const callOrder: string[] = [];
    let seenError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        callOrder.push('onError');
        seenError = error;
      },
      afterSession: async () => {
        callOrder.push('afterSession');
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(undefined), promptBuilder, undefined, {hooks});

    const outcome = await orchestrator.processMessage(sessionWith('hello')).then(
      () => ({rejected: false}),
      reason => ({rejected: true, reason})
    );

    expect(outcome).toEqual({rejected: true, reason: undefined});
    expect(callOrder).toEqual(['onError', 'afterSession']);
    expect(seenError).toBeInstanceOf(Error);
    expect(seenError?.message).toBe('undefined');
    expect(seenError?.cause).toBe(undefined);
  });

  it('calls onError with the same Error instance when an Error is thrown', async () => {
    const callOrder: string[] = [];
    let seenError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        callOrder.push('onError');
        seenError = error;
      },
      afterSession: async () => {
        callOrder.push('afterSession');
      },
    };

    const originalError = new Error('original');
    const orchestrator = createChatOrchestrator(rejectingWith(originalError), promptBuilder, undefined, {hooks});

    const outcome = await orchestrator.processMessage(sessionWith('hello')).then(
      () => ({rejected: false}),
      reason => ({rejected: true, reason})
    );

    expect(outcome).toEqual({rejected: true, reason: originalError});
    expect(callOrder).toEqual(['onError', 'afterSession']);
    expect(seenError).toBe(originalError);
  });
});

